exercises.solution:
function formatarReais(centavos) {
  return `R$ ${(centavos / 100).toFixed(2).replace('.', ',')}`;
}

const sacola = [
  { nome: 'Tomate', quilos: 2, precoCentavos: 790 },
  { nome: 'Banana', quilos: 3, precoCentavos: 450 },
  { nome: 'Cebola', quilos: 1, precoCentavos: 300 },
];

let total = 0;
for (const item of sacola) {
  total = total + item.quilos * item.precoCentavos;
}
console.log(`Total da feira: ${formatarReais(total)}`);

const passos = [8200, 10500, 4300, 12000, 9700, 10100, 3200];

let total = 0;
let diasNaMeta = 0;
for (const dia of passos) {
  total = total + dia;
  if (dia >= 10000) {
    diasNaMeta = diasNaMeta + 1;
  }
}

console.log(`Total: ${total} passos`);
console.log(`Média por dia: ${Math.round(total / passos.length)} passos`);
console.log(`Dias na meta: ${diasNaMeta} de ${passos.length}`);

